/* Örnek resimler: imread("cameraman.tif") ve imread("football.jpg") bunları okur.
   Ham piksel verisi (satır-öncelikli) base64 olarak gömülüdür; file:// ile açıldığında da çalışır.
   Kaynaklar:
   - cameraman: klasik "cameraman" test görüntüsü (telif: Massachusetts Institute of Technology), scikit-image v0.17.2 veri kümesindeki kopyadan 256×256'ya küçültüldü. Yalnızca kişisel çalışma içindir; yeniden dağıtma.
   - football: "American football ball.jpg", Petey21, CC0 (Wikimedia Commons), 256×320'ye kırpılıp küçültüldü. MATLAB'ın kendi football.jpg dosyası DEĞİLDİR; aynı boyutta (256×320×3) benzer bir resimdir. */
(function (g) {
  var R = [
    { ad: 'cameraman', h: 256, w: 256, kanal: 1, b64: '' },
    { ad: 'football', h: 256, w: 320, kanal: 3, b64: '' }
  ];
  g.ORNEK_RESIMLER = R;
  var M = g.MiniMatlab || (typeof require === 'function' ? (function () { try { return require('../js/matlab.js'); } catch (e) { return null; } })() : null);
  if (M && M.registerImage) R.forEach(function (r) {
    var s = typeof atob === 'function' ? atob(r.b64) : Buffer.from(r.b64, 'base64').toString('binary');
    var d = new Uint8Array(s.length); for (var i = 0; i < s.length; i++) d[i] = s.charCodeAt(i);
    M.registerImage(r.ad, r.h, r.w, r.kanal, d);
  });
  if (typeof module !== 'undefined') module.exports = R;
})(typeof window !== 'undefined' ? window : globalThis);
